private monitorProcess(
  proc: ReturnType<typeof spawn>,
  _conversationId: string
): Promise<AgentProcessResult> {
  return new Promise((resolve) => {
    let buffer = "";
    const allEvents: ChatEvent[] = [];
    let fullResponse = "";
    let errorMessage: string | undefined;

    // Collect stdout
    proc.stdout?.on("data", (data: Buffer) => {
      const chunk = data.toString();
      buffer += chunk;

      // Process complete lines
      const lines = buffer.split("\n");
      buffer = lines.pop() || "";

      const lineChunk = lines.join("\n");
      if (lineChunk) {
        const events = this.parseOutput(lineChunk);
        allEvents.push(...events);

        // Accumulate text content
        for (const event of events) {
          if (event.type === "text" && event.content) {
            fullResponse += event.content;
          }
        }
      }
    });

    // Collect stderr for errors
    proc.stderr?.on("data", (data: Buffer) => {
      const error = data.toString();
      if (error.trim()) {
        errorMessage = error;
      }
    });

    // Handle process completion
    proc.on("close", (exitCode) => {
      // Process any remaining buffer
      if (buffer.trim()) {
        const events = this.parseOutput(buffer);
        allEvents.push(...events);
        for (const event of events) {
          if (event.type === "text" && event.content) {
            fullResponse += event.content;
          }
        }
      }

      // Add completion event
      allEvents.push({ type: "complete" });

      resolve({
        exitCode: exitCode || 0,
        fullResponse,
        events: allEvents,
        error: errorMessage,
      });
    });

    // Handle process errors
    proc.on("error", (error) => {
      allEvents.push({
        type: "error",
        error: error.message,
      });

      resolve({
        exitCode: 1,
        fullResponse,
        events: allEvents,
        error: error.message,
      });
    });
  });
}

/**
 * Base Chat Client Interface
 *
 * Defines the abstraction layer for AI chat clients that can be used with
 * the Documentation Robotics CLI. Implementations include Claude Code CLI
 * and GitHub Copilot CLI.
 */

/**
 * Chat message in a conversation
 */
export interface ChatMessage {
  role: "user" | "assistant" | "system";
  content: string;
