/**
 * Execute spec reference upgrade
 */

source:
async function executeSpecUpgrade(projectRoot: string, action: UpgradeAction): Promise<void> {
  const operationSpan = isTelemetryEnabled
    ? startSpan("upgrade.spec", {
        "upgrade.spec.from_version": action.fromVersion || "none",
        "upgrade.spec.to_version": action.toVersion,
        "upgrade.spec.is_reinstall": !action.fromVersion,
      })
    : null;

  try {
    console.log(ansis.dim(`Installing spec reference v${action.toVersion}...`));
    await installSpecReference(projectRoot, true);
    console.log(ansis.green(`✓ Spec reference upgraded to v${action.toVersion}`));

    if (operationSpan) {
      operationSpan.setAttribute("upgrade.spec.result", "success");
    }
  } catch (error) {
    if (operationSpan) {
      operationSpan.recordException(error as Error);
      operationSpan.setStatus({
        code: 2, // SpanStatusCode.ERROR
        message: getErrorMessage(error),
      });
      operationSpan.setAttribute("upgrade.spec.result", "error");
    }
    console.error(
      ansis.red(
        `Error upgrading spec reference: ${getErrorMessage(error)}`
      )
    );
    throw error;
  } finally {
    endSpan(operationSpan);
  }
}

format(): string {
  const lines: string[] = [];

  lines.push(ansis.red(`Error: ${this.message}`));

  if (this.context?.operation) {
    lines.push(ansis.dim(`During: ${this.context.operation}`));
  }

  if (this.context?.partialProgress) {
    const { completed, total } = this.context.partialProgress;
    lines.push(
      ansis.yellow(`⚠ Partial progress: ${completed}/${total} completed (operation rolled back)`)
    );
  }

  if (this.context?.relatedElements && this.context.relatedElements.length > 0) {
    lines.push(ansis.dim("Related elements:"));
    for (const elem of this.context.relatedElements.slice(0, MAX_SUGGESTIONS)) {
      lines.push(ansis.dim(`  • ${elem}`));
    }
    if (this.context.relatedElements.length > MAX_SUGGESTIONS) {
      lines.push(
        ansis.dim(`  ... and ${this.context.relatedElements.length - MAX_SUGGESTIONS} more`)
      );
    }
  }

  if (this.suggestions && this.suggestions.length > 0) {
    lines.push("");
    lines.push(ansis.dim("Suggestions:"));
    for (const suggestion of this.suggestions) {
      lines.push(ansis.dim(`  • ${suggestion}`));
    }
  }

  return lines.join("\n");
}

