export class SemanticValidator {
  /**
   * Validate semantic constraints of a model
   */
  async validateModel(model: Model): Promise<ValidationResult> {
    const result = new ValidationResult();

    this.validateRelationshipPredicates(model, result);
    this.validateApmInferredWithoutSdk(model, result);

    return result;
  }

  /**
   * Rule: apm_inferred_without_sdk
   *
   * When the APM layer contains MetricInstrument, Span, TraceConfiguration, or
   * ExporterConfig elements and ALL of them have source_reference.provenance = "inferred",
   * emit a WARNING suggesting OTel SDK verification.
   *
   * Rationale: The APM skill's checklist can cause Claude to add instrumentation
   * elements without verifying that an OTel SDK is present. This validator surfaces
   * the accuracy concern on every subsequent `dr validate` run.
   */
  private validateApmInferredWithoutSdk(model: Model, result: ValidationResult): void {
    const apmLayer = model.layers.get("apm");
    if (!apmLayer) {
      return;
    }

    const instrumentationTypes = new Set(["metricinstrument", "span", "traceconfiguration", "exporterconfig"]);
    const instrumentationElements = apmLayer.listElements().filter((e) =>
      instrumentationTypes.has(e.type)
    );

    if (instrumentationElements.length === 0) {
      return;
    }

    const allInferred = instrumentationElements.every(
      (e) => e.source_reference?.provenance === "inferred"
    );

    if (allInferred) {
      result.addWarning({
        layer: "apm",
        elementId: "apm.*",
        message:
          `All ${instrumentationElements.length} APM instrumentation element(s) have provenance: inferred. ` +
          "If no @opentelemetry SDK exists in package.json, these elements are aspirational rather than " +
          "implemented. Consider marking them as such in their descriptions.",
        fixSuggestion:
          "Run: grep '@opentelemetry' package.json — if absent, update element descriptions to note " +
          "that instrumentation is aspirational and no OTel export is implemented.",
      });
    }
  }

  /**
   * Validate relationship predicates against the generated spec relationship index.
   * RELATIONSHIPS_BY_PREDICATE is compiled from all spec relationship schema files,
   * so it is always consistent with the spec without manual synchronization.
   */
  private validateRelationshipPredicates(model: Model, result: ValidationResult): void {
    for (const [layerName, layer] of model.layers) {
      for (const element of layer.listElements()) {
        for (const rel of element.relationships || []) {
          if (!RELATIONSHIPS_BY_PREDICATE.has(rel.predicate)) {
            result.addWarning({
              layer: layerName,
              elementId: element.path || element.id,
              message: `Relationship predicate '${rel.predicate}' is not defined in any spec relationship schema`,
              fixSuggestion: `Run 'dr catalog types' to list valid predicates, or 'dr catalog search ${rel.predicate}' to find the correct predicate`,
            });
          }
        }
      }
    }
  }
}

export class CoverageAnalyzer {
  constructor(private catalog: RelationshipCatalog) {}

  /**
   * Analyze coverage for all layers
   * @returns Result object indicating success/partial/failure with complete flag
   */
  async analyzeAll(): Promise<CoverageAnalysisResult> {
    const layers = getAllLayers();
    const results: CoverageMetrics[] = [];
    const errors: Array<{ layer: string; error: Error }> = [];

    for (const layer of layers) {
      try {
        const metrics = await this.analyzeLayer(layer);
        results.push(metrics);
      } catch (error) {
        errors.push({
          layer: layer.id,
          error: error instanceof Error ? error : new Error(String(error)),
        });
      }
    }

    // If all layers failed, throw the first error
    if (results.length === 0 && errors.length > 0) {
      throw errors[0].error;
    }

    // Report partial failures to user
    if (errors.length > 0 && results.length > 0) {
      console.error(
        `\n⚠️  Warning: Coverage analysis failed for ${errors.length} layer(s):`
      );
      for (const { layer, error } of errors) {
        console.error(`  - ${layer}: ${error.message}`);
      }
      console.error(
        `\nSuccessfully analyzed ${results.length}/${layers.length} layers.\n`
      );
    }

    return {
      results,
      failures: errors,
      isComplete: errors.length === 0,
    };
  }

  /**
   * Analyze coverage for a single layer
   */
  async analyzeLayer(layer: LayerMetadata): Promise<CoverageMetrics> {
    const nodeTypes = layer.nodeTypes;
    const nodeTypeCount = nodeTypes.length;

    // Count relationships per node type
    const relationshipCounts = new Map<string, number>();
    const usedPredicatesSet = new Set<string>();

    for (const nodeType of nodeTypes) {
      const relationships = RELATIONSHIPS_BY_SOURCE.get(nodeType) || [];
      relationshipCounts.set(nodeType, relationships.length);

      // Track used predicates
      for (const rel of relationships) {
        usedPredicatesSet.add(rel.predicate);
      }
    }

    // Calculate total relationships
    const relationshipCount = Array.from(relationshipCounts.values()).reduce(
      (sum, count) => sum + count,
      0
    );

    // Identify isolated node types (zero relationships)
    const isolatedNodeTypes = nodeTypes.filter(
      (type) => (relationshipCounts.get(type) || 0) === 0
    );
    const isolationPercentage = createPercentage(
      nodeTypeCount > 0 ? (isolatedNodeTypes.length / nodeTypeCount) * 100 : 0
    );

    // Get available predicates for this layer
    const availablePredicates = await this.getAvailablePredicatesForLayer(
      layer.id
    );
    // Filter used predicates to only include those defined in relationship schemas for this layer
    // This handles cases where relationship index contains predicates not yet formalized in schemas
    const availablePredicateSet = new Set(availablePredicates);
    const usedPredicates = Array.from(usedPredicatesSet).filter(
      (p) => availablePredicateSet.has(p)
    );
    const utilizationPercentage = createPercentage(
      availablePredicates.length > 0
        ? (usedPredicates.length / availablePredicates.length) * 100
        : 0
    );

    // Calculate density
    const relationshipsPerNodeType =
      nodeTypeCount > 0 ? relationshipCount / nodeTypeCount : 0;

    // Standard alignment (for ArchiMate layers)
    const standardAlignment = await this.analyzeStandardAlignment(layer);

    return {
      layer: layer.id,
      nodeTypeCount,
      relationshipCount,
      interLayerRelationshipCount: 0,
      isolatedNodeTypes,
      isolationPercentage,
      availablePredicates,
      usedPredicates,
      utilizationPercentage,
      relationshipsPerNodeType,
      standardAlignment,
    };

