export function validateRelationshipCombination(
  sourceSpecNodeId: string,
  predicate: string,
  destSpecNodeId: string
): { valid: boolean; suggestions?: string[] } {
  const valid =
    getValidRelationships(sourceSpecNodeId, predicate, destSpecNodeId).length >
    0;

  if (valid) {
    return { valid: true };
  }

  // Generate helpful suggestions
  const suggestions: string[] = [];
  const validPredicates = getValidPredicatesForSource(sourceSpecNodeId);

  if (validPredicates.length > 0) {
    suggestions.push(
      `Valid predicates for ${sourceSpecNodeId}: ${validPredicates.join(", ")}`
    );
  } else {
    suggestions.push(`No valid relationships defined for ${sourceSpecNodeId}`);
  }

  // If predicate is provided, show valid destinations
  if (predicate) {
    const validDests = getValidDestinationsForSourceAndPredicate(
      sourceSpecNodeId,
      predicate
    );
    if (validDests.length > 0) {
      suggestions.push(
        `Valid destinations for --[${predicate}]-->: ${validDests.join(", ")}`
      );
    } else {
      suggestions.push(
        `No valid destinations for ${sourceSpecNodeId} --[${predicate}]-->`
      );
    }
  }

  return { valid: false, suggestions };
}

removeNode(nodeId: string): boolean {
  const node = this.nodes.get(nodeId);
  if (!node) {
    return false;
  }

  // Remove from nodes map
  this.nodes.delete(nodeId);

  // Remove from layer index
  const layerSet = this.indices.nodesByLayer.get(node.layer);
  if (layerSet) {
    layerSet.delete(nodeId);
    if (layerSet.size === 0) {
      this.indices.nodesByLayer.delete(node.layer);
    }
  }

  // Remove from type index
  const typeSet = this.indices.nodesByType.get(node.type);
  if (typeSet) {
    typeSet.delete(nodeId);
    if (typeSet.size === 0) {
      this.indices.nodesByType.delete(node.type);
    }
  }

  // Remove all edges involving this node
  const edgesInvolving: string[] = [];
  for (const [edgeId, edge] of this.edges.entries()) {
    if (edge.source === nodeId || edge.destination === nodeId) {
      edgesInvolving.push(edgeId);
    }
  }
  for (const edgeId of edgesInvolving) {
    this.removeEdge(edgeId);
  }

  // Increment version to invalidate caches
  this.nodesVersion++;
  return true;
}

