static calculateStats(model: Model): ValidationStats {
  const stats: ValidationStats = {
    totalElements: 0,
    totalRelationships: 0,
    elementsPerLayer: {},
    relationshipsByPredicate: {},
    orphanedElements: [],
  };

  const elementIds = new Set<string>();
  const crossLayerRefCounts = new Map<string, number>();

  // Count elements and cross-layer references (element.references[])
  for (const [layerName, layer] of model.layers) {
    let layerCount = 0;
    for (const element of layer.listElements()) {
      elementIds.add(element.path || element.id);
      layerCount++;
      stats.totalElements++;

      const refCount = (element.references || []).length;
      crossLayerRefCounts.set(element.path || element.id, refCount);
      stats.totalRelationships += refCount;

      for (const ref of element.references || []) {
        const predicate = ref.type || "references";
        stats.relationshipsByPredicate[predicate] =
          (stats.relationshipsByPredicate[predicate] || 0) + 1;
      }
    }

    if (layerCount > 0) {
      stats.elementsPerLayer[layerName] = layerCount;
    }
  }

  // Also count intra-layer relationships from relationships.yaml
  const intraLayerRels = model.relationships.getAll();
  stats.totalRelationships += intraLayerRels.length;
  const connectedViaIntraLayer = new Set<string>();
  for (const rel of intraLayerRels) {
    stats.relationshipsByPredicate[rel.predicate] =
      (stats.relationshipsByPredicate[rel.predicate] || 0) + 1;
    connectedViaIntraLayer.add(rel.source);
    connectedViaIntraLayer.add(rel.target);
  }

  // Find orphaned elements: no cross-layer refs and not touched by any intra-layer relationship
  for (const elementId of elementIds) {
    if (connectedViaIntraLayer.has(elementId)) {
      continue;
    }

    const outgoingCrossLayer = crossLayerRefCounts.get(elementId) || 0;
    let incomingCrossLayer = 0;
    for (const [, layer] of model.layers) {
      for (const element of layer.listElements()) {
        for (const ref of element.references || []) {
          if (ref.target === elementId) {
            incomingCrossLayer++;
          }
        }
      }
    }

    if (outgoingCrossLayer === 0 && incomingCrossLayer === 0) {
      stats.orphanedElements.push(elementId);
    }
  }

  return stats;
}

/**
 * Relationship Schema Validation with Cardinality Enforcement
 *
 * Validates relationships against their spec relationship schemas, including:
 * - Schema compliance (source/destination node types)
 * - Cardinality constraints (one-to-one, one-to-many, many-to-one, many-to-many)
 * - Predicate validity
 * - Relationship attributes against schema
 */

import { ValidationResult } from "./types.js";
import type { Model } from "../core/model.js";
import type { Relationship } from "../core/relationships.js";
import { fileURLToPath } from "url";
import path from "path";
import { readFile } from "../utils/file-io.js";
import { existsSync } from "fs";
import { startActiveSpan } from "../telemetry/index.js";

interface ManifestDistFile {
  layers: Array<{ id: string }>;
}

interface LayerDistFile {
  relationshipSchemas: Record<string, {
    id: string;
    source_spec_node_id: string;
    source_layer: string;
    destination_spec_node_id: string;
    destination_layer: string;
    predicate: string;
    cardinality: "one-to-one" | "one-to-many" | "many-to-one" | "many-to-many";
    strength: string;
    required?: boolean;
    attributes?: Record<string, unknown>;
  }>;
}

declare const TELEMETRY_ENABLED: boolean | undefined;
const isTelemetryEnabled = typeof TELEMETRY_ENABLED !== "undefined" ? TELEMETRY_ENABLED : false;

export interface RelationshipSchema {
  id: string;
  source_spec_node_id: string;
  source_layer: string;
  destination_spec_node_id: string;
  destination_layer: string;
  predicate: string;
  cardinality: "one-to-one" | "one-to-many" | "many-to-one" | "many-to-many";
  strength: string;
  required?: boolean;
  attributes?: Record<string, unknown>;
}

/**
 * Validator for relationship schema compliance and cardinality constraints
 *
 * Validates that relationships:
 * 1. Conform to their spec relationship schemas
 * 2. Respect cardinality constraints (e.g., one-to-one means max 1 relationship of that type)
 * 3. Reference valid predicates
 * 4. Have valid source/destination element types
 */
export class RelationshipValidator {
  private schemasDir: string;
  private relationshipSchemas: Map<string, RelationshipSchema> = new Map();

  constructor() {
    const __dirname = path.dirname(fileURLToPath(import.meta.url));
    this.schemasDir = path.join(__dirname, "..", "schemas", "bundled");
  }

  /**
   * Initialize and load relationship schemas
   */
  async initialize(): Promise<void> {
    await this.loadRelationshipSchemas();
  }

  /**
   * Load relationship schemas from compiled bundled spec (manifest.json + per-layer JSON files)
   */
  private async loadRelationshipSchemas(): Promise<void> {
    const manifestPath = path.join(this.schemasDir, "manifest.json");

    if (!existsSync(manifestPath)) {
      throw new Error(`Bundled manifest not found at ${manifestPath}`);
    }

    const manifestContent = await readFile(manifestPath);
    const manifest = JSON.parse(manifestContent) as ManifestDistFile;

    for (const { id: layerId } of manifest.layers) {
      const layerPath = path.join(this.schemasDir, `${layerId}.json`);
      if (!existsSync(layerPath)) {
        continue;
      }

      try {
        const layerContent = await readFile(layerPath);
        const layerData = JSON.parse(layerContent) as LayerDistFile;

        for (const [relId, relSchema] of Object.entries(layerData.relationshipSchemas || {})) {
          this.relationshipSchemas.set(relId, {
            id: relSchema.id || relId,
            source_spec_node_id: relSchema.source_spec_node_id || "",
            source_layer: relSchema.source_layer || "",
            destination_spec_node_id: relSchema.destination_spec_node_id || "",
            destination_layer: relSchema.destination_layer || "",
            predicate: relSchema.predicate || "",
            cardinality: relSchema.cardinality || "many-to-many",
            strength: relSchema.strength || "medium",
            required: relSchema.required || false,
            attributes: relSchema.attributes,
          });
        }
      } catch (error: any) {
        throw new Error(`Failed to load relationship schemas for layer '${layerId}': ${error.message}`);
      }
    }

export class SemanticValidator {
  /**
   * Validate semantic constraints of a model
   */
  async validateModel(model: Model): Promise<ValidationResult> {
    const result = new ValidationResult();

    this.validateRelationshipPredicates(model, result);
    this.validateApmInferredWithoutSdk(model, result);

    return result;
  }

  /**
   * Rule: apm_inferred_without_sdk
   *
   * When the APM layer contains MetricInstrument, Span, TraceConfiguration, or
   * ExporterConfig elements and ALL of them have source_reference.provenance = "inferred",
   * emit a WARNING suggesting OTel SDK verification.
   *
   * Rationale: The APM skill's checklist can cause Claude to add instrumentation
   * elements without verifying that an OTel SDK is present. This validator surfaces
   * the accuracy concern on every subsequent `dr validate` run.
   */
  private validateApmInferredWithoutSdk(model: Model, result: ValidationResult): void {
    const apmLayer = model.layers.get("apm");
    if (!apmLayer) {
      return;
    }

    const instrumentationTypes = new Set(["metricinstrument", "span", "traceconfiguration", "exporterconfig"]);
    const instrumentationElements = apmLayer.listElements().filter((e) =>
      instrumentationTypes.has(e.type)
    );

    if (instrumentationElements.length === 0) {
      return;
    }

    const allInferred = instrumentationElements.every(
      (e) => e.source_reference?.provenance === "inferred"
    );

    if (allInferred) {
      result.addWarning({
        layer: "apm",
        elementId: "apm.*",
        message:
          `All ${instrumentationElements.length} APM instrumentation element(s) have provenance: inferred. ` +
          "If no @opentelemetry SDK exists in package.json, these elements are aspirational rather than " +
          "implemented. Consider marking them as such in their descriptions.",
        fixSuggestion:
          "Run: grep '@opentelemetry' package.json — if absent, update element descriptions to note " +
          "that instrumentation is aspirational and no OTel export is implemented.",
      });
    }
  }

  /**
   * Validate relationship predicates against the generated spec relationship index.
   * RELATIONSHIPS_BY_PREDICATE is compiled from all spec relationship schema files,
   * so it is always consistent with the spec without manual synchronization.
   */
  private validateRelationshipPredicates(model: Model, result: ValidationResult): void {
    for (const [layerName, layer] of model.layers) {
      for (const element of layer.listElements()) {
        for (const rel of element.relationships || []) {
          if (!RELATIONSHIPS_BY_PREDICATE.has(rel.predicate)) {
            result.addWarning({
              layer: layerName,
              elementId: element.path || element.id,
              message: `Relationship predicate '${rel.predicate}' is not defined in any spec relationship schema`,
              fixSuggestion: `Run 'dr catalog types' to list valid predicates, or 'dr catalog search ${rel.predicate}' to find the correct predicate`,
            });
          }
        }
      }
    }
  }
}

