async function handleUpgrade(
  projectRoot: string,
  actions: UpgradeAction[],
  options: UpgradeOptions,
  integrationUpToDate: string[] = [],
  parentSpan: any = null
): Promise<void> {
  // Display upgrade plan
  if (actions.length > 0) {
    console.log(ansis.bold("Upgrade Plan:\n"));

    for (const action of actions) {
      const versionChange = action.fromVersion
        ? `${action.fromVersion} → ${action.toVersion}`
        : `v${action.toVersion}`;

      const icon = action.type === "spec" ? "📦" : action.type === "integration" ? "🔌" : "🔄";
      console.log(ansis.yellow(`${icon} ${action.description}`));
      console.log(ansis.dim(`   Version: ${versionChange}`));

      if (action.details && action.details.length > 0) {
        for (const detail of action.details) {
          console.log(ansis.dim(`   • ${detail}`));
        }
      }
      console.log();
    }
  }

  // Display integration status for up-to-date integrations
  if (integrationUpToDate.length > 0) {
    console.log(ansis.bold("Integration Status:"));
    integrationUpToDate.forEach((msg) => console.log(msg));
    console.log();
  }

  // Handle dry-run mode
  if (options.dryRun) {
    console.log(ansis.yellow("[DRY RUN] No changes will be made\n"));
    if (parentSpan) {
      parentSpan.setAttribute("upgrade.dry_run_completed", true);
    }
    return;
  }

  // Prompt for confirmation unless --yes flag is set
  let shouldProceed = options.yes;
  if (!shouldProceed) {
    // Check if we're in an interactive terminal
    const isInteractive = process.stdin.isTTY && process.stdout.isTTY;

    if (isInteractive) {
      const response = await confirm({
        message: "Proceed with upgrade?",
      });
      shouldProceed = response === true;
    } else {
      const error = new Error("Non-interactive mode requires --yes flag to proceed with upgrade");
      if (parentSpan) {
        parentSpan.recordException(error);
        parentSpan.setAttribute("upgrade.result", "non_interactive_abort");
      }
      console.error(
        ansis.red("Error: Non-interactive mode requires --yes flag to proceed with upgrade")
      );
      throw error;
    }
  }

  if (!shouldProceed) {
    console.log(ansis.dim("\nUpgrade cancelled\n"));
    if (parentSpan) {
      parentSpan.setAttribute("upgrade.user_cancelled", true);
    }
    return;
  }

  console.log(ansis.bold("\nExecuting upgrades...\n"));

  // Execute actions in order: spec, model, then integrations
  for (const action of actions) {
    if (action.type === "spec") {
      await executeSpecUpgrade(projectRoot, action);
    } else if (action.type === "model") {
      await executeModelMigration(action, options);
    } else if (action.type === "integration") {
      await executeIntegrationUpdate(action.description, async () => {
        if (action.integrationName === "claude") {
          const m = new ClaudeIntegrationManager();
          await m.upgrade({ force: true }); // force=true skips internal prompts (user confirmed above)
        } else {
          const m = new CopilotIntegrationManager();
          await m.upgrade({ force: true });
        }
      });
    }
  }

  console.log(ansis.green("\n✓ All upgrades completed successfully!\n"));
}

private cloneLayer(layer: Layer): Layer {
  const cloned = new LayerClass(layer.name);

  // Clone all elements (shallow copy - read-only in projection)
  for (const element of layer.listElements()) {
    const elementClone = new ElementClass({
      id: element.id,
      path: element.path,
      spec_node_id: element.spec_node_id,
      type: element.type,
      layer_id: element.layer_id,
      name: element.name,
      description: element.description,
      attributes: { ...element.attributes },
      references: [...(element.references || [])],
      relationships: [...(element.relationships || [])],
      layer: element.layer,
      source_reference: element.source_reference,
      metadata: element.metadata,
    });
    cloned.addElement(elementClone);
  }

  // Preserve layer metadata if present
  if (layer.metadata) {
    cloned.metadata = { ...layer.metadata };
  }

  // Mark as clean to prevent projection from being saved
  cloned.markClean();
  return cloned;
}

import type { Model } from "../core/model.js";
import type { Exporter, ExportOptions, ExportFormatInfo } from "./types.js";

/**
 * ExportManager - Registry and dispatcher for format-specific exporters
 */
export class ExportManager {
  private exporters: Map<string, Exporter> = new Map();
  private formatInfo: Map<string, ExportFormatInfo> = new Map();

  /**
   * Register an exporter for a specific format
   */
  register(
    format: string,
    exporter: Exporter,
    info: Omit<ExportFormatInfo, "format" | "name" | "supportedLayers">
  ): void {
    this.exporters.set(format, exporter);
    this.formatInfo.set(format, {
      format,
      name: exporter.name,
      supportedLayers: exporter.supportedLayers,
      ...info,
    });
  }

  /**
   * Check if a format is registered
   */
  hasFormat(format: string): boolean {
    return this.exporters.has(format);
  }

  /**
   * Export model to specified format
   */
  async export(model: Model, format: string, options: ExportOptions = {}): Promise<string> {
    const exporter = this.exporters.get(format);
    if (!exporter) {
      throw new Error(`Unknown export format: ${format}`);
    }

    // Validate that requested layers are supported
    if (options.layers) {
      const unsupported = options.layers.filter(
        (layer) => !exporter.supportedLayers.includes(layer)
      );
      if (unsupported.length > 0) {
        throw new Error(
          `Format '${format}' does not support layers: ${unsupported.join(", ")}. ` +
            `Supported layers: ${exporter.supportedLayers.join(", ")}`
        );
      }
    }

    return await exporter.export(model, options);
  }

  /**
   * Get list of available formats
   */
  listFormats(): string[] {
    return Array.from(this.exporters.keys()).sort();
  }

  /**
   * Get metadata about a format
   */
  getFormatInfo(format: string): ExportFormatInfo | undefined {
    return this.formatInfo.get(format);
  }

  /**
   * Get supported layers for a format
   */
  getSupportedLayers(format: string): string[] {
    const exporter = this.exporters.get(format);
    return exporter?.supportedLayers ?? [];
  }

  /**
   * Get all registered formats with metadata
   */
  getAllFormats(): ExportFormatInfo[] {
    return Array.from(this.formatInfo.values()).sort((a, b) => a.format.localeCompare(b.format));
  }
}

export abstract class BaseChatClient {
  protected currentSession?: ChatSession;

  /**
   * Check if the chat CLI tool is available on the system
   * @returns Promise that resolves to true if available, false otherwise
   */
  abstract isAvailable(): Promise<boolean>;

  /**
   * Send a message and stream the response
   * @param message The user's message
   * @param options Chat options including agent, working directory, and session
   * @returns Promise that resolves with the complete assistant response text
   */
  abstract sendMessage(message: string, options?: ChatOptions): Promise<string>;

  /**
   * Get the current session information
   * @returns Current session or undefined if no session exists
   */
  getCurrentSession(): ChatSession | undefined {
    return this.currentSession;
  }

  /**
   * Clear the current session
   */
  clearSession(): void {
    this.currentSession = undefined;
  }

  /**
   * Create a new session
   * @returns The newly created session
   */
  protected createSession(): ChatSession {
    const session: ChatSession = {
      id: this.generateSessionId(),
      createdAt: new Date(),
      lastMessageAt: new Date(),
    };
    this.currentSession = session;
    return session;
  }

  /**
   * Update the last message timestamp for the current session
   */
  protected updateSessionTimestamp(): void {
    if (this.currentSession) {
      this.currentSession.lastMessageAt = new Date();
    }
  }

  /**
   * Generate a unique session ID
   * @returns A unique session identifier
   */
  protected generateSessionId(): string {
    return `session-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
  }

  /**
   * Get the name of this chat client (for display purposes)
   */
  abstract getClientName(): string;
}

export interface ChatOptions {
  /** Optional agent/skill name to use */
  agent?: string;
  /** Working directory for the chat */
  workingDirectory?: string;
  /** Optional session ID to continue a conversation */
  sessionId?: string;
  /** Enable dangerous mode (skip permissions for Claude, allow all tools for Copilot) */
  withDanger?: boolean;
  /**
   * Stream for real-time text output. Defaults to process.stdout.
   * Pass process.stderr to keep stdout clean for programmatic callers.
   * Pass null to suppress text output entirely.
   * Tool-use notifications always go to process.stderr regardless of this setting.
   */
  outputStream?: NodeJS.WriteStream | null;
}

