import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { isTelemetryEnabled, startActiveSpan } from "../telemetry/index.js";
import {
  annotationCreateTool,
  annotationDeleteTool,
  annotationGetTool,
  annotationListTool,
  annotationReplyTool,
  annotationUpdateTool,
  changesetListTool,
  changesetShowTool,
  chatLaunchTool,
  chatStatusTool,
