/**
 * Delete existing layer reports and regenerate all 13 markdown reports.
 */
export async function reportsRegenerateCommand(): Promise<void> {
  try {
    const projectRoot = await findProjectRoot();
    if (!projectRoot) {
      console.error(ansis.red("Error: No DR project found"));
      console.error(ansis.dim('Run "dr init" to create a new project'));
      process.exit(1);
    }

    await regenerateLayerReports(projectRoot);
  } catch (error) {
    console.error(ansis.red(`Error: ${getErrorMessage(error)}`));
    process.exit(1);
  }
}

/**
 * Delete existing reports directory and regenerate all 13 layer reports and the README.
 * Exported for use in the upgrade command.
 */
export async function regenerateLayerReports(projectRoot: string): Promise<void> {
  const reportDir = path.join(projectRoot, "documentation-robotics", "reports");

  // Remove the entire reports directory so stale reports from removed/renamed layers don't linger.
  // force: true means no error if the directory doesn't exist yet.
  // ModelReportOrchestrator.regenerateAll() recreates the directory before writing.
  console.log(ansis.dim("Removing existing reports..."));
  await fs.rm(reportDir, { recursive: true, force: true });

  // Load model and regenerate all reports
  console.log(ansis.dim("Loading model..."));
  const model = await Model.load(projectRoot);

  const orchestrator = new ModelReportOrchestrator(model, projectRoot);
  console.log(ansis.dim("Generating 13 layer reports and README..."));
  await orchestrator.regenerateAll();

  console.log(ansis.green("✓ All 13 layer reports and README regenerated"));
  console.log(ansis.dim("  Reports written to: documentation-robotics/reports/"));
  console.log(ansis.dim("  README written to: documentation-robotics/README.md"));
}

/**
 * Check whether any layer reports exist in the reports directory.
 * Returns false if the directory doesn't exist or contains no .md files.
 */
export async function hasLayerReports(projectRoot: string): Promise<boolean> {
  const reportDir = path.join(projectRoot, "documentation-robotics", "reports");
  try {
    const entries = await fs.readdir(reportDir);
    return entries.some((f) => f.endsWith(".md"));
  } catch (error: unknown) {
    const err = error as NodeJS.ErrnoException;
    if (err.code === "ENOENT") return false;
    throw error;
  }
}

export class OpenAPIExporter implements Exporter {
  name = "OpenAPI";
  supportedLayers = ["api"];

  async export(model: Model, _options: ExportOptions = {}): Promise<string> {
    const span = isTelemetryEnabled ? startSpan("export.format.openapi") : null;

    try {
      // Load API layer elements
      const apiLayer = await model.getLayer("api");
      if (!apiLayer) {
        throw new Error("No API layer found in model");
      }
      const elements = apiLayer.listElements();
      if (elements.length === 0) {
        throw new Error("No API layer found in model");
      }

      // Note: _options is not used for OpenAPI exporter as it only supports the api layer
      // The parameter is kept for interface consistency with other exporters

      const spec: OpenAPISpec = {
        openapi: "3.0.0",
        info: {
          title: model.manifest.name,
          version: model.manifest.version || "1.0.0",
        },
        paths: {},
        components: {
          schemas: {},
          responses: {},
          parameters: {},
          requestBodies: {},
          headers: {},
          securitySchemes: {},
        },
      };

      if (model.manifest.description) {
        spec.info.description = model.manifest.description;
      }

      // Group operations by operationId-derived path
      const pathGroups = new Map<string, EndpointMapping[]>();

      // Iterate layer elements for operation/endpoint nodes
      for (const element of elements) {
        if (element.type === "operation" || element.type === "endpoint") {
          const operationId =
            (element.attributes?.operationId as string) || element.name;

          // Derive URL path from element attributes (for endpoints) or slug (for operations)
          let pathKey: string;
          const attrPath = element.attributes?.path as string;
          if (attrPath) {
            // Use path from attributes (e.g., "/api/orders")
            pathKey = attrPath;
          } else {
            // Derive URL path from element slug (last segment of path)
            // e.g., api.operation.get-user-profile → /get-user-profile
            const slugSegment = (element as { path?: string }).path?.split(".").pop();
            pathKey = slugSegment ? `/${slugSegment}` : `/${operationId}`;
          }

          // Infer HTTP method from operationId prefix keywords or use method attribute
          const method = ((element.attributes?.method as string) || (() => {
            const opIdLower = operationId.toLowerCase();
            if (/^(create|post|add|insert|register|submit|send)/.test(opIdLower)) {
              return "post";
            } else if (/^(update|put|edit|modify|replace|set|save)/.test(opIdLower)) {
              return "put";
            } else if (/^(patch|partial)/.test(opIdLower)) {
              return "patch";
            } else if (/^(delete|remove|destroy|purge|clear|unregister)/.test(opIdLower)) {
              return "delete";
            }
            return "get";
          })()).toLowerCase();

          if (!pathGroups.has(pathKey)) {
            pathGroups.set(pathKey, []);
          }

          const endpointData: EndpointData = {
            name: (element.attributes?.summary as string) || element.name,
            id: element.id,
            description: element.description,
            getProperty: (key: string) => element.attributes?.[key],
            getSourceReference: () => element.getSourceReference(),
          };

          pathGroups.get(pathKey)!.push({ method, element: endpointData });
        }
      }

      // Build paths section
      for (const [path, endpoints] of pathGroups) {
        const pathItem: Record<string, unknown> = {};

        for (const { method, element } of endpoints) {
          const operation: Record<string, unknown> = {
            summary: element.name,
            operationId: (element.getProperty("operationId") as string) || element.id,
            responses: element.getProperty("responses") || {
              "200": {
                description: "Successful response",
              },
            },
          };

          if (element.description) {
            operation.description = element.description;
          }

          const tags = element.getProperty("tags");
          if (tags) {
            operation.tags = Array.isArray(tags) ? tags : [tags];
