  const operationSpan = isTelemetryEnabled
    ? startSpan("upgrade.integration", {
        "upgrade.integration.label": label,
        "upgrade.integration.type": label.includes("Claude")
          ? "claude"
          : label.includes("Copilot")
          ? "copilot"
          : "unknown",
      })
