/**
   * Handle JSON-RPC 2.0 messages for chat functionality
   */

source:
private async handleJSONRPCMessage(ws: HonoWSContext, data: WSMessage): Promise<void> {
  // Only requests have a method; responses have result/error
  if (!('method' in data)) {
    // This is a response, not something we handle in this function
    // Log unexpected protocol patterns for operational visibility
    const responseType = ('result' in data) ? 'success' : ('error' in data) ? 'error' : 'unknown';
    const msgId = ('id' in data) ? data.id : 'unknown';
    console.warn(
      `[WebSocket] Received JSON-RPC ${responseType} response from client (ID: ${msgId}), ignoring`
    );
    return;
  }
  const rpcMsg = data as JSONRPCRequest;
  const { method, params, id } = rpcMsg;

  // Helper to send JSON-RPC response
  const sendResponse = (result: any) => {
    ws.send(
      JSON.stringify({
        jsonrpc: "2.0",
        result,
        id,
      })
    );
  };

  // Helper to send JSON-RPC error
  const sendError = (code: number, message: string, data?: any) => {
    ws.send(
      JSON.stringify({
        jsonrpc: "2.0",
        error: { code, message, data },
        id,
      })
    );
  };

  try {
    switch (method) {
      case "chat.status":
        // Check if any chat client is available
        const hasClient = this.selectedChatClient !== undefined;

        // Determine error message: initialization error takes precedence
        let statusError: string | null = null;
        if (this.chatInitializationError) {
          statusError = `Chat initialization failed: ${this.chatInitializationError.message}`;
        } else if (!hasClient) {
          statusError = "No chat client available. Install Claude Code or GitHub Copilot.";
        }

        sendResponse({
          sdk_available: hasClient,
          sdk_version: hasClient ? this.selectedChatClient!.getClientName() : null,
          error_message: statusError,
        });
        break;

      case "chat.send":
        // Validate params
        if (!params || typeof params !== 'object' || !('message' in params) || typeof (params as any).message !== 'string' || (params as any).message.trim() === '') {
          sendError(JSONRPC_ERRORS.INVALID_PARAMS, "Message cannot be empty");
          return;
        }

        // Check if chat client is available
        if (!this.selectedChatClient) {
          sendError(
            JSONRPC_ERRORS.NO_CLIENT_AVAILABLE,
            "No chat client available. Install Claude Code or GitHub Copilot to enable chat."
          );
          return;
        }

        // Generate conversation ID
        const conversationId = `conv-${++this.chatConversationCounter}-${Date.now()}`;

        // Launch chat with selected client
        await this.launchChat(ws, conversationId, (params as any).message, id);
        break;

      case "chat.cancel":
        // Find and cancel any active conversation
        let cancelled = false;
        let cancelledConvId = null;

        for (const [convId, process] of this.activeChatProcesses) {
          try {
            process.kill();
            this.activeChatProcesses.delete(convId);
            cancelled = true;
            cancelledConvId = convId;
            break;
          } catch (error) {
            console.warn(`[Chat] Failed to cancel process for conversation ${convId}: ${getErrorMessage(error)}`);
          }
        }

        sendResponse({
          cancelled,
          conversation_id: cancelledConvId,
        });
        break;

      default:
        sendError(JSONRPC_ERRORS.METHOD_NOT_FOUND, `Method not found: ${method}`);
    }
  } catch (error) {
    const errorMsg = getErrorMessage(error);
    sendError(JSONRPC_ERRORS.INTERNAL_ERROR, "Internal error", errorMsg);
  }
}

/**
 * model_delete — delete an element (optionally cascading to dependents).
 * Mirrors `dr delete`, but since an MCP session has no interactive confirmation
 * channel, the caller must pass `force` or `cascade` explicitly when dependents
 * exist rather than being prompted; operates through the shared MutationHandler.
 */

import { z } from "zod";
import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
import { DependencyTracker, TraceDirection } from "../../core/dependency-tracker.js";
import { MutationHandler } from "../../core/mutation-handler.js";
import { ReferenceRegistry } from "../../core/reference-registry.js";
import { findElementLayer } from "../../utils/element-utils.js";
import { CLIError, ErrorCategory, getErrorMessage } from "../../utils/errors.js";
import { jsonResult, loadModel, rootPathSchema, runTool, type McpToolDefinition } from "./shared.js";

const inputSchema = {
  id: z.string().describe("Element ID or path to delete."),
  cascade: z.boolean().optional().describe("Also delete elements that depend on this one."),
  force: z.boolean().optional().describe("Skip the dependency check and delete only this element, even if others depend on it."),
  dryRun: z.boolean().optional().describe("Preview what would be deleted without making changes."),
  rootPath: rootPathSchema,
};

export type ModelDeleteArgs = z.infer<z.ZodObject<typeof inputSchema>>;

export async function modelDeleteHandler(args: ModelDeleteArgs): Promise<CallToolResult> {
  return runTool(async () => {
    const model = await loadModel(args.rootPath);

    const layerName = await findElementLayer(model, args.id);
    if (!layerName) {
      throw new CLIError(`Element ${args.id} not found`, ErrorCategory.NOT_FOUND, [
        'Use "model_search" to find similar elements',
      ]);
    }

    const layer = (await model.getLayer(layerName))!;
    const element = layer.getElement(args.id);
    if (!element) {
      throw new CLIError(`Element ${args.id} not found`, ErrorCategory.NOT_FOUND, [
        'Use "model_search" to find similar elements',
      ]);
    }

    // Cascade is scoped to cross-layer references only, matching `dr delete`. This is
    // narrower than "model_trace", which also follows intra-layer relationships.yaml
    // edges — a dependent found by model_trace may not be included in a cascade delete.
    const registry = new ReferenceRegistry();
    for (const l of model.layers.values()) {
      for (const el of l.listElements()) {
        registry.registerElement(el);
      }
    }
    const tracker = new DependencyTracker(registry, model);
    const dependents = tracker.traceDependencies(args.id, TraceDirection.DOWN, null);

    if (dependents.length > 0 && !args.cascade && !args.force) {
      throw new CLIError("Element has dependencies", ErrorCategory.USER, [
        "Use cascade=true to remove all dependent elements",
        "Use dryRun=true with cascade=true to preview what would be deleted",
        "Or use force=true to remove only this element (dependencies will reference a non-existent element)",
      ]);
    }

    const elementsToRemove = args.cascade ? [args.id, ...dependents] : [args.id];

    if (args.dryRun) {
      return jsonResult({
        status: "dry-run",
        id: args.id,
        layer: layerName,
        elementsToRemove,
      });
    }

    let deletedCount = 0;
    const skippedDependents: string[] = [];
    const cascadeDeleted: string[] = [];
    if (args.cascade && dependents.length > 0) {
      for (const depId of [...dependents].reverse()) {
        const depLayerName = await findElementLayer(model, depId);
        if (!depLayerName) {
          console.error(`[mcp] model_delete: cascade dependent "${depId}" not found, skipping`);
          skippedDependents.push(depId);
          continue;
        }

        const depLayer = (await model.getLayer(depLayerName))!;
        const depElement = depLayer.getElement(depId);
        if (!depElement) {
          console.error(`[mcp] model_delete: cascade dependent "${depId}" not found, skipping`);
          skippedDependents.push(depId);
          continue;
        }

        const depHandler = new MutationHandler(model, depId, depLayerName);
        try {
          await depHandler.executeDelete(depElement);
        } catch (error) {
          throw new CLIError(
            `Failed to delete dependent element "${depId}": ${getErrorMessage(error)}`,
            ErrorCategory.SYSTEM,
            [
              `${cascadeDeleted.length} dependent element(s) were deleted before the error`,
              'Use "model_validate" to check the model for broken references',
              `"${args.id}" was not deleted — you can retry the operation once dependents are resolved`,
            ],
            {
              operation: "model_delete (cascade)",
              relatedElements: cascadeDeleted,
              partialProgress: { completed: cascadeDeleted.length, total: dependents.length },
            }
          );
        }
        cascadeDeleted.push(depId);
        deletedCount++;
      }
    }

