/**
 * Utilities for call graph analysis
 */

import { relative } from "node:path";
import type { CallGraphNode } from "./types.js";

/**
 * Valid edge types for call graph edges
 */
type EdgeType = "CALLS" | "HTTP_CALLS" | "HANDLES";

/**
 * Type guard to ensure a value is a valid edge type
 */
function isEdgeType(value: unknown): value is EdgeType {
  return value === "CALLS" || value === "HTTP_CALLS" || value === "HANDLES";
}

/**
 * Clamp depth to valid range (default 3, min 0, max 10)
 */
export function clampDepth(depth: number | undefined): number {
  return Math.max(Math.min(depth ?? 3, 10), 0);
}

/**
 * Shape raw response node to CallGraphNode
 */
export function shapeCallGraphNode(
  responseNode: any,
  projectRoot?: string
): CallGraphNode {
  // Extract source file and compute relative path if projectRoot provided
  let sourceFile = responseNode.file_path || responseNode.source_file || "";
  if (sourceFile && projectRoot) {
    try {
      // Validate inputs are strings before calling path.relative()
      if (typeof sourceFile !== "string" || typeof projectRoot !== "string") {
        throw new TypeError(
          `Invalid path types: sourceFile=${typeof sourceFile}, projectRoot=${typeof projectRoot}`
        );
      }
      sourceFile = relative(projectRoot, sourceFile);
    } catch (error) {
      // Log the error but keep the original path
      const errorMessage = error instanceof Error ? error.message : String(error);
      console.warn(
        `Warning: Failed to compute relative path for "${sourceFile}": ${errorMessage}`
      );
    }
  }

  return {
    qualified_name: responseNode.qualified_name || responseNode.id,
    source_file: sourceFile,
    source_symbol: responseNode.source_symbol || responseNode.id || "",
    depth: typeof responseNode.depth === "number" ? responseNode.depth : 0,
    edge_type: "CALLS",
  };
}

/**
 * Determine edge type based on node depth and edges list
 */
export function determineEdgeType(
  nodeDepth: number,
  edges: Array<{ from_node: string; to_node: string; type?: string }>,
  targetNodeQualifiedName: string,
  validEdgeTypes: string[] = ["CALLS", "HTTP_CALLS", "HANDLES"]
): EdgeType {
  const defaultEdgeType = validEdgeTypes[0] || "CALLS";

  // For root nodes (depth 0), always use default
  if (nodeDepth === 0) {
    // Validate that default is a known edge type
    if (!isEdgeType(defaultEdgeType)) {
      return "CALLS"; // Fallback to safe default
    }
    return defaultEdgeType;
  }

  // For non-root nodes, find incoming edge
  const incomingEdge = edges.find(
    (edge) => edge.to_node === targetNodeQualifiedName
  );
  if (incomingEdge && incomingEdge.type && validEdgeTypes.includes(incomingEdge.type)) {
    // Validate that the edge type is known
    if (isEdgeType(incomingEdge.type)) {
      return incomingEdge.type;
    }
  }

  // Return validated default
  if (!isEdgeType(defaultEdgeType)) {
    return "CALLS"; // Fallback to safe default
  }
  return defaultEdgeType;
}

export class VirtualProjectionEngine {
  private stagingAreaManager: StagedChangesetStorage;
  private projectionCache: ProjectionCache;

  /**
   * Create a new projection engine.
   *
   * @param rootPath - Root path to the model (used by StagedChangesetStorage)
   */
  constructor(rootPath: string) {
    this.stagingAreaManager = new StagedChangesetStorage(rootPath);
    this.projectionCache = {
      cache: new Map(),
      metrics: new Map(),
      maxAge: 5 * 60 * 1000, // 5-minute TTL for cached projections
      lastCleanup: Date.now(),
    };
  }

  /**
   * Project a single element by applying staged changes to it.
   * Merges the element's base state with staged changes to compute its projected state.
   *
   * @param baseModel - The base model to project from
   * @param changesetId - ID of the changeset containing staged changes
   * @param elementId - ID of the element to project
   * @returns Projected element with staged changes applied, or null if element is deleted
   * @throws Error if changeset not found
   *
   * @remarks
   * If multiple changes exist for the element, the last change determines final state.
   * For 'delete' operations, returns null.
   * For 'add' operations without base element, creates new element from staged data.
   * For 'update' operations, merges staged changes with base element attributes.
   */
  async projectElement(
    baseModel: Model,
    changesetId: string,
    elementId: string
  ): Promise<Element | null> {
    const changeset = await this.stagingAreaManager.load(changesetId);
    if (!changeset) {
      throw new Error(`Changeset '${changesetId}' not found`);
    }

    // Find all changes for this element across all layers
    const elementChanges = changeset.changes.filter(
      (c: Change) => c.elementId === elementId
    ) as StagedChange[];

    if (elementChanges.length === 0) {
      // No changes, return base element if it exists
      return baseModel.getElementById(elementId) || null;
    }

    // Get the last change to determine the element's final state
    const lastChange = elementChanges[elementChanges.length - 1];

    if (lastChange.type === "delete") {
      return null;
    }

    // For add or update, construct the projected element
    const baseElement = baseModel.getElementById(elementId);
    const projectedData = lastChange.after || {};

    if (baseElement) {
      // Create a new element with projected data merged with base
      const projectedAttributes =
        typeof projectedData.attributes === "object" ? projectedData.attributes : {};

      const mergedData = {
        id: baseElement.id,
        path: baseElement.path,
        spec_node_id: baseElement.spec_node_id,
        type: typeof projectedData.type === "string" ? projectedData.type : baseElement.type,
        layer_id: baseElement.layer_id,
        name: typeof projectedData.name === "string" ? projectedData.name : baseElement.name,
        description:
          typeof projectedData.description === "string"
            ? projectedData.description
            : baseElement.description,
        attributes: {
          ...baseElement.attributes,
          ...projectedAttributes,
        },
        references: Array.isArray(projectedData.references)
          ? projectedData.references
          : baseElement.references,
        relationships: Array.isArray(projectedData.relationships)
          ? projectedData.relationships
          : baseElement.relationships,
        source_reference: baseElement.source_reference,
        metadata: baseElement.metadata,
      };

      return new ElementClass(mergedData);
    } else if (lastChange.type === "add") {
      // New element being added
      return new ElementClass({
        id: (lastChange.after?.id as string) || elementId,
        path: (lastChange.after?.path as string) || elementId,
        spec_node_id: (lastChange.after?.spec_node_id as string) || "",
        type: (projectedData.type as string) || "unknown",
        layer_id: lastChange.layerName,
        name: (projectedData.name as string) || elementId,
        description: (projectedData.description as string) || "",
        attributes: (typeof projectedData.attributes === "object"
          ? projectedData.attributes
          : {}) as Record<string, unknown>,
        references: Array.isArray(projectedData.references) ? projectedData.references : [],
        relationships: Array.isArray(projectedData.relationships)
          ? projectedData.relationships
          : [],
        source_reference: projectedData.source_reference as SourceReference | undefined,
        metadata: projectedData.metadata as ElementMetadata | undefined,
        layer: lastChange.layerName,
      });
    }

