      if (!afterMap.has(beforeCoverage.layer)) {
        skipped.push({
          layer: beforeCoverage.layer,
          reason: "only-in-before",
          coverage: beforeCoverage,
        });
      }
    }

    for (const afterCoverage of after) {
      const beforeCoverage = beforeMap.get(afterCoverage.layer);
      if (!beforeCoverage) {
