    let aiAborted = false;
    try {
      await aiEvaluator.evaluateLowCoverageElements(beforeResult.coverage as CoverageMetrics[], getPredicatesForLayer);
    } catch (error) {
      if (error instanceof AIEvaluationAbortError) {
