export async function addRelationshipHandler(
  model: Model,
  source: string,
  target: string,
  predicate: string,
  properties?: Record<string, unknown>,
  preResolved?: PreResolvedElements
): Promise<boolean> {
  // Use pre-resolved elements if provided, otherwise resolve them
  let resolvedSourceLayerName = preResolved?.source?.layerName;
  let resolvedSourceElement = preResolved?.source?.element;
  let resolvedTargetLayerName = preResolved?.target?.layerName;
  let resolvedTargetElement = preResolved?.target?.element;

  if (!resolvedSourceLayerName) {
    resolvedSourceLayerName = await findElementLayer(model, source);
    if (!resolvedSourceLayerName) {
      throw new CLIError(
        `Source element ${source} not found`,
        ErrorCategory.USER
      );
    }
  }

  if (!resolvedSourceElement) {
    const sourceLayer = await model.getLayer(resolvedSourceLayerName);
    if (!sourceLayer) {
      throw new CLIError(
        `Source element ${source} not found`,
        ErrorCategory.USER
      );
    }
    resolvedSourceElement = sourceLayer.getElement(source);
    if (!resolvedSourceElement) {
      throw new CLIError(
        `Source element ${source} not found`,
        ErrorCategory.USER
      );
    }
  }

  if (!resolvedTargetLayerName) {
    resolvedTargetLayerName = await findElementLayer(model, target);
    if (!resolvedTargetLayerName) {
      throw new CLIError(
        `Target element ${target} not found`,
        ErrorCategory.USER
      );
    }
  }

  if (!resolvedTargetElement) {
    const targetLayer = await model.getLayer(resolvedTargetLayerName);
    if (!targetLayer) {
      throw new CLIError(
        `Target element ${target} not found`,
        ErrorCategory.USER
      );
    }
    resolvedTargetElement = targetLayer.getElement(target);
    if (!resolvedTargetElement) {
      throw new CLIError(
        `Target element ${target} not found`,
        ErrorCategory.USER
      );
    }
  }

  // Schema-driven validation
  const sourceSpecNodeId = constructSpecNodeId(resolvedSourceElement, source);
  const targetSpecNodeId = constructSpecNodeId(resolvedTargetElement, target);

  const validation = validateRelationshipCombination(
    sourceSpecNodeId,
    predicate,
    targetSpecNodeId
  );

  if (!validation.valid) {
    throw new CLIError(
      `Invalid relationship: ${source} --[${predicate}]--> ${target}`,
      ErrorCategory.USER,
      validation.suggestions
    );
  }

  {
    const catalog = new RelationshipCatalog();
    await catalog.load();
    const relType = catalog.getTypeByPredicate(predicate);
    if (relType && !relType.semantics.reflexivity && source === target) {
      throw new CLIError(
        `Invalid relationship: predicate "${predicate}" does not allow reflexive relationships (${source})`,
        ErrorCategory.USER
      );
    }
  }

  // Guard against duplicate relationships before staging or writing
  if (model.relationships.find(source, target, predicate).length > 0) {
    // Return false to signal duplicate; caller will emit appropriate output
    return false;
  }

  // Check for active changeset — stage relationship instead of writing directly
  const stagingManager = new StagingAreaManager(model.rootPath, model);
  const activeChangesetId = await stagingManager.getActiveId();

  const relData = {
    source,
    target,
    predicate,
    layer: resolvedSourceLayerName,
    ...(resolvedTargetLayerName !== resolvedSourceLayerName
      ? { targetLayer: resolvedTargetLayerName }
      : {}),
    category: "structural" as const,
    ...(properties ? { properties } : {})
  };

private generateLayerIndex(data: ModelReadmeData): string {
  const lines: string[] = [];
  lines.push('## Layer Reports\n');
  lines.push('\n');

  const headers = ['Layer', 'Elements', 'Report'];
  const rows: string[][] = [];

  // Sort layers by layer number for consistent ordering
  const sortedLayers = [...data.layers].sort((a, b) => a.layerNumber - b.layerNumber);

  for (const layer of sortedLayers) {
    const layerName = formatLayerName(layer.layerName);
    const elementCount = String(layer.elementCount);

    let report: string;
    if (layer.elementCount > 0) {
      // Create link to layer report (in reports/ subdirectory)
      report = `[${layer.reportFileName}](./reports/${layer.reportFileName})`;
    } else {
      // No link for empty layers
      report = '—';
    }

    rows.push([layerName, elementCount, report]);
  }

  const table = formatMarkdownTable(headers, rows);
  lines.push(table);
  lines.push('\n');

  return lines.join('');
}

/**
 * Integration Management Types
 *
 * Defines the core data structures for managing Claude Code and GitHub Copilot
 * integrations, matching the Python CLI's integration manager patterns.
 */

/**
 * Component configuration matching Python COMPONENTS dict structure
 * Describes how a component should be copied from source to target
 */
export interface ComponentConfig {
  /** Source directory name in integrations/{integration}/ */
  source: string;

  /** Target directory in project (.claude/ or .github/) */
  target: string;

  /** Human-readable description of this component */
  description: string;

  /** Optional file prefix filter (e.g., "dr-" to only copy dr-*.md) */
  prefix?: string;

  /** Whether component contains individual files or subdirectories */
  type: "files" | "dirs";

  /**
   * Whether this component is DR-owned (tracked in version file for updates)
   * Set to false for user-customizable components like templates
   * Defaults to true if not specified
   */
  tracked?: boolean;
}

/**
 * Version file YAML schema (.dr-version, .dr-copilot-version)
 * Tracks installation metadata and file hashes for change detection
 */
export interface VersionData {
  /** CLI version that installed this integration */
  version: string;

  /** ISO 8601 timestamp when integration was installed/updated */
  installed_at: string;

  /** Mapping of component names to their installed file hashes */
  components: {
    [componentName: string]: {
      [fileName: string]: {
        /** SHA256 hash truncated to 8 characters */
        hash: string;

        /** True if installed file differs from the source (user-modified or hash unreadable) */
        modified: boolean;
      };
    };
  };
}

/**
 * Validate VersionData deserialization result
 *
 * Ensures that the YAML-deserialized object has the required structure
 * and types. Catches corrupted version files early.
 *
 * @param data Deserialized object from YAML
 * @returns VersionData if valid
 * @throws Error if validation fails
 */
export function validateVersionData(data: unknown): VersionData {
  if (typeof data !== "object" || data === null) {
    throw new Error("Version data must be an object");
  }

  const obj = data as Record<string, unknown>;

  if (typeof obj.version !== "string") {
    throw new Error('Missing or invalid "version" field in version file');
  }

  if (typeof obj.installed_at !== "string") {
    throw new Error('Missing or invalid "installed_at" field in version file');
  }

  if (typeof obj.components !== "object" || obj.components === null) {
    throw new Error('Missing or invalid "components" field in version file');
  }

  // Basic structure validation - deeper structure verified on access
  return obj as unknown as VersionData;
}

