export async function startActiveSpan<T>(
  name: string,
  fn: (span: Span) => Promise<T>,
  attributes?: Record<string, any>
): Promise<T> {
  if (!isTelemetryEnabled || !tracer) {
    // Create a no-op span for the callback
    const noopSpan = {
      end: () => {},
      setAttribute: () => noopSpan,
      setAttributes: () => noopSpan,
      addEvent: () => noopSpan,
      setStatus: () => noopSpan,
      updateName: () => noopSpan,
      isRecording: () => false,
      recordException: () => {},
      spanContext: () => ({
        traceId: "",
        spanId: "",
        traceFlags: 0,
      }),
    } as any;
    return fn(noopSpan);
  }

  // Use tracer.startActiveSpan for proper context propagation
  return new Promise<T>((resolve, reject) => {
    tracer!.startActiveSpan(name, { attributes }, async (span) => {
      try {
        const result = await fn(span);
        span.end();
        resolve(result);
      } catch (error) {
        span.recordException(error as Error);
        span.end();
        reject(error);
      }
    });
  });
}

private async saveInterLayerValidation(
  pairKey: string,
  validation: InterLayerValidation
): Promise<void> {
  const filename = `${pairKey.replace("->", "_to_")}.json`;
  const filepath = join(this.config.outputDir, "inter-layer-validation", filename);

  try {
    await writeFile(
      filepath,
      JSON.stringify(
        {
          pair: pairKey,
          timestamp: new Date().toISOString(),
          validation,
        },
        null,
        2
      )
    );
  } catch (error: unknown) {
    const errorMessage = getErrorMessage(error);
    throw new Error(
      `Failed to save inter-layer validation for "${pairKey}" to ${filepath}: ${errorMessage}. ` +
        `AI evaluation results were not persisted. Please ensure the output directory is writable and has sufficient disk space.`
    );
  }
}

