/**
 * Fetch-based OTLP exporter for Bun compatibility.
 * Uses native fetch API instead of Node.js http module.
 */

import type { SpanExporter, ReadableSpan } from "@opentelemetry/sdk-trace-base";
import type { ExportResult } from "@opentelemetry/core";
import { ExportResultCode } from "@opentelemetry/core";
import { getErrorMessage } from "../utils/errors.js";

/**
 * OTLP exporter using fetch API for Bun compatibility.
 * Bun's http module has compatibility issues with the standard OTLP exporter,
 * so we use fetch which is natively supported by Bun.
 */
export class FetchOTLPExporter implements SpanExporter {
  private readonly url: string;
  private readonly debug: boolean;
  private readonly timeoutMs: number;

  constructor(config?: { url?: string; timeoutMillis?: number }) {
    this.url = config?.url || "http://localhost:4318/v1/traces";
    this.timeoutMs = config?.timeoutMillis ?? 10000;
    this.debug =
      process.env.DR_TELEMETRY_DEBUG === "1" ||
      process.env.DEBUG === "1" ||
      process.env.VERBOSE === "1";

    if (this.debug) {
      process.stderr.write(`[TELEMETRY] Fetch-based trace exporter initialized: ${this.url}\n`);
    }
  }

  export(spans: ReadableSpan[], resultCallback: (result: ExportResult) => void): void {
    if (this.debug) {
      process.stderr.write(`[TELEMETRY] Exporting ${spans.length} span(s) to ${this.url}\n`);
    }

    // Convert spans to OTLP JSON format
    const payload = this.convertSpansToOTLP(spans);

    // Use AbortController for timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.timeoutMs);

    fetch(this.url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
      signal: controller.signal,
    })
      .then(async (response) => {
        clearTimeout(timeoutId);

        if (response.ok) {
          if (this.debug) {
            process.stderr.write(`[TELEMETRY] Export SUCCESS - ${spans.length} span(s) sent\n`);
          }
          resultCallback({ code: ExportResultCode.SUCCESS });
        } else {
          const errorText = await response.text();
          if (this.debug) {
            process.stderr.write(
              `[TELEMETRY] Export FAILED - HTTP ${response.status}: ${errorText}\n`
            );
          }
          resultCallback({
            code: ExportResultCode.FAILED,
            error: new Error(`HTTP ${response.status}: ${errorText}`),
          });
        }
      })
      .catch((error) => {
        clearTimeout(timeoutId);
        if (this.debug) {
          const errorMsg = getErrorMessage(error);
          process.stderr.write(`[TELEMETRY] Export FAILED - ${errorMsg}\n`);
        }
        resultCallback({
          code: ExportResultCode.FAILED,
          error: error instanceof Error ? error : new Error(String(error)),
        });
      });
  }

  async forceFlush(): Promise<void> {
    // No-op for fetch-based exporter (no buffering)
  }

  async shutdown(): Promise<void> {
    // No-op for fetch-based exporter (no persistent connections)
  }

  /**
   * Convert OpenTelemetry spans to OTLP JSON format.
   * Simplified version that covers the essential fields.
   */
  private convertSpansToOTLP(spans: ReadableSpan[]): any {
    return {
      resourceSpans: [
        {
          resource: {
            attributes: this.convertAttributes(spans[0]?.resource?.attributes || {}),
          },
          scopeSpans: [
            {
              scope: {
                name: spans[0]?.instrumentationLibrary?.name || "unknown",
                version: spans[0]?.instrumentationLibrary?.version || "",
              },
              spans: spans.map((span) => ({
                traceId: span.spanContext().traceId,
                spanId: span.spanContext().spanId,
                parentSpanId: span.parentSpanId || undefined,
                name: span.name,
                kind: span.kind,
                startTimeUnixNano: String(span.startTime[0] * 1e9 + span.startTime[1]),
                endTimeUnixNano: String(span.endTime[0] * 1e9 + span.endTime[1]),

export class Manifest {
  name: string;
  version: string;
  description?: string;
  author?: string;
  created: string;
  modified: string;
  cliVersion?: string;
  specVersion?: string;
  changeset_history?: ChangesetHistoryEntry[];
  models?: Record<string, ExternalModelDeclaration>;
  codebase_path?: string;

  constructor(data: ManifestData) {
    this.name = data.name;
    this.version = data.version;
    this.description = data.description;
    this.author = data.author;
    this.created = data.created ?? new Date().toISOString();
    this.modified = data.modified ?? new Date().toISOString();
    this.cliVersion = data.cliVersion;
    this.specVersion = data.specVersion;
    this.models = data.models;
    this.codebase_path = data.codebase_path;

    // Migrate changeset history from legacy format (if present)
    this.changeset_history = this.migrateChangesetHistory(data.changeset_history);
  }

  /**
   * Migrate changeset history from legacy field names to new format
   * Legacy format: applied_at → committed_at, action: "applied" → action: "committed"
   *
   * @param history - Changeset history from manifest (may use legacy field names)
   * @returns Migrated changeset history using new field names
   * @throws Error if action value is unrecognized (not "committed", "discarded", "applied", or "reverted")
   */
  private migrateChangesetHistory(
    history: ChangesetHistoryEntry[] | undefined
  ): ChangesetHistoryEntry[] {
    if (!history || history.length === 0) {
      return [];
    }

    return history.map((entry: any) => {
      // Validate action value to prevent silent data corruption
      let action: "committed" | "discarded";
      if (entry.action === "applied" || entry.action === "committed") {
        action = "committed";
      } else if (entry.action === "reverted" || entry.action === "discarded") {
        action = "discarded";
      } else {
        throw new Error(
          `Invalid changeset history action '${entry.action}' for changeset '${entry.name}'. ` +
          `Expected: committed, discarded, applied (legacy), or reverted (legacy).`
        );
      }

      return {
        name: entry.name,
        // Handle legacy field name: applied_at → committed_at
        committed_at: entry.committed_at || entry.applied_at || new Date().toISOString(),
        action,
      };
    });
  }

  /**
   * Update the modified timestamp to current time
   */
  updateModified(): void {
    this.modified = new Date().toISOString();
  }

  /**
   * Serialize to JSON representation
   *
   * Converts the Manifest to a JSON-serializable object that includes project
   * metadata, changeset history, and external model declarations.
   *
   * @returns ManifestData object suitable for JSON serialization
   */
  toJSON(): Record<string, unknown> {
    const result: Record<string, unknown> = {
      name: this.name,
      version: this.version,
      created: this.created,
      modified: this.modified,
    };

    if (this.description) {
      result.description = this.description;
    }

    if (this.author) {
      result.author = this.author;
    }

    if (this.cliVersion) {
      result.cliVersion = this.cliVersion;
    }

    if (this.specVersion) {
      result.specVersion = this.specVersion;
    }

    if (this.codebase_path) {
      result.codebase_path = this.codebase_path;
    }

    if (this.changeset_history && this.changeset_history.length > 0) {
      result.changeset_history = this.changeset_history;
    }

    if (this.models && Object.keys(this.models).length > 0) {
      result.models = this.models;
    }

    return result;
  }

