export async function modelSearchHandler(args: ModelSearchArgs): Promise<CallToolResult> {
  return runTool(async () => {
    if (!args.query && !args.sourceFile && !args.layer && !args.type) {
      throw new CLIError(
        "At least one of query, sourceFile, layer, or type must be provided",
        ErrorCategory.USER,
        ['Use "model_list" to list all elements without filtering']
      );
    }

    if (args.layer && !isValidLayer(args.layer)) {
      const validLayers = getAllLayerIds();
      const similar = findSimilar(args.layer, validLayers, 3);
      const suggestions: string[] = [`Use a valid layer name: ${formatValidOptions(validLayers)}`];
      if (similar.length > 0) suggestions.unshift(`Did you mean: ${similar.join(" or ")}?`);
      throw new CLIError(`Unknown layer "${args.layer}"`, ErrorCategory.USER, suggestions);
    }

    if (args.type) {
      const candidateTypes = args.layer
        ? Array.from(NODE_TYPES.values()).filter((t) => t.layer === args.layer)
        : Array.from(NODE_TYPES.values());
      const isKnownType = candidateTypes.some((t) => t.type === args.type);
      if (!isKnownType) {
        const validTypeNames = Array.from(new Set(candidateTypes.map((t) => t.type))).sort();
        const similar = findSimilar(args.type, validTypeNames, 3);
        const suggestions: string[] = [
          args.layer
            ? `Valid types for ${args.layer}: ${formatValidOptions(validTypeNames)}`
            : `Valid types: ${formatValidOptions(validTypeNames)}`,
        ];
        if (similar.length > 0) suggestions.unshift(`Did you mean: ${similar.join(" or ")}?`);
        throw new CLIError(
          `Unknown element type "${args.type}"${args.layer ? ` for layer "${args.layer}"` : ""}`,
          ErrorCategory.USER,
          suggestions
        );
      }
    }

    const model = await loadModel(args.rootPath);
    const isSourceFileSearch = !!args.sourceFile;
    const queryLower = (args.query ?? "").toLowerCase();

    const results: Array<{
      layer: string;
      id: string;
      type: string;
      name: string;
      description?: string;
      sourceFile?: string;
      sourceSymbol?: string;
    }> = [];

    for (const layerName of model.getLayerNames()) {
      if (args.layer && layerName !== args.layer) continue;

      const layerObj = await model.getLayer(layerName);
      if (!layerObj) continue;

      for (const element of layerObj.listElements()) {
        if (args.type && element.type !== args.type) continue;

        if (isSourceFileSearch) {
          if (!matchesSourceFile(element, args.sourceFile!)) continue;
        } else {
          const displayId = element.path || element.id;
          const idMatch = displayId.toLowerCase().includes(queryLower);
          const nameMatch = element.name.toLowerCase().includes(queryLower);
          if (!idMatch && !nameMatch) continue;
        }

        let sourceFile: string | undefined;
        let sourceSymbol: string | undefined;
        const sourceRef = element.getSourceReference();
        if (sourceRef?.locations && sourceRef.locations.length > 0) {
          sourceFile = sourceRef.locations[0].file;
          sourceSymbol = sourceRef.locations[0].symbol;
        }

        results.push({
          layer: layerName,
          id: element.path || element.id,
          type: element.type,
          name: element.name,
          description: element.description,
          sourceFile,
          sourceSymbol,
        });
      }
    }

    return jsonResult({
      query: args.query ?? "",
      sourceFile: args.sourceFile,
      count: results.length,
      results,
    });
  });
}

protected getSourceRoot(): string {
  // Get the path to the compiled CLI directory
  // import.meta.url points to the compiled .js file, e.g., dist/integrations/base-manager.js
  const cliDir = dirname(fileURLToPath(import.meta.url));

  // Production: dist/integrations/{integrationSourceDir}/
  // The integrations/ directory is in the same dist/ folder as cli.js
  const prodPath = join(cliDir, this.integrationSourceDir);
  if (existsSync(prodPath)) {
    return prodPath;
  }

  // Development: integrations/{integrationSourceDir}/ relative to repo root
  // From dist/integrations/base-manager.js, go up 3 levels to repo root
  const repoRoot = dirname(dirname(dirname(dirname(cliDir))));
  const devPath = join(repoRoot, "integrations", this.integrationSourceDir);
  if (existsSync(devPath)) {
    return devPath;
  }

  throw new Error(
    `Integration source directory not found for ${this.integrationSourceDir}. ` +
      `Checked: ${prodPath} and ${devPath}`
  );
}

/**
 * Verify report formatters
 * Supports text (default), JSON, and markdown output formats for verification reports
 */

import ansis from "ansis";
import type { VerifyReport, MatchedEntry, GraphOnlyEntry, ModelOnlyEntry, IgnoredEntry } from "../analyzers/types.js";
import { formatDate } from "../utils/date-utils.js";
import { escapeMarkdown } from "./markdown-utils.js";

export type VerifyReportFormat = "text" | "json" | "markdown";

export interface VerifyFormatterOptions {
  format: VerifyReportFormat;
}

/**
 * Format verify report for output
 */
export function formatVerifyReport(report: VerifyReport, options: VerifyFormatterOptions): string {
  const format: VerifyReportFormat = options.format;
  switch (format) {
    case "json":
      return formatVerifyJSON(report);
    case "markdown":
      return formatVerifyMarkdown(report);
    case "text":
      return formatVerifyText(report);
    default:
      // Exhaustive check: if this line is reached, options.format is not a valid VerifyReportFormat
      const _exhaustive: never = format;
      return _exhaustive;
  }
}

/**
 * Format as JSON
 */
export function formatVerifyJSON(report: VerifyReport): string {
  return JSON.stringify(report, null, 2) + "\n";
}

/**
 * Format as Markdown
 */
export function formatVerifyMarkdown(report: VerifyReport): string {
  const lines: string[] = [];

  // Header
  lines.push(`# API Verification Report`);
  lines.push("");
  lines.push(`**Project:** ${escapeMarkdown(report.project_root)}`);
  lines.push(`**Generated:** ${formatDate(report.generated_at)}`);
  lines.push(`**Analyzer:** ${escapeMarkdown(report.analyzer)} (indexed: ${formatDate(report.analyzer_indexed_at)})`);
  lines.push("");

  // Table of Contents
  lines.push("## Contents");
  lines.push("- [Changeset Context](#changeset-context)");
  lines.push("- [Summary](#summary)");
  lines.push("- [Matched Entries](#matched-entries)");
  lines.push("- [Graph-only Entries (Gaps)](#graph-only-entries-gaps)");
  lines.push("- [Model-only Entries (Drift)](#model-only-entries-drift)");
  lines.push("- [Ignored Entries](#ignored-entries)");
  lines.push("");

  // Changeset context
  formatChangesetContextMarkdown(lines, report);
  lines.push("");

  // Summary section
  formatSummaryMarkdown(lines, report);
  lines.push("");

  // Matched section
  formatMatchedMarkdown(lines, report.buckets.matched);
  lines.push("");

  // Graph-only section (gaps)
  formatGraphOnlyMarkdown(lines, report.buckets.in_graph_only);
  lines.push("");

  // Model-only section (drift)
  formatModelOnlyMarkdown(lines, report.buckets.in_model_only);
  lines.push("");

  // Ignored section
  formatIgnoredMarkdown(lines, report.buckets.ignored);
  lines.push("");

  return lines.join("\n");
}

/**
 * Format changeset context for markdown output
 */
function formatChangesetContextMarkdown(lines: string[], report: VerifyReport): void {
  const context = report.changeset_context;

  lines.push("## Changeset Context");

  if (context.active_changeset) {
    lines.push(`- **Active Changeset:** ${escapeMarkdown(context.active_changeset)}`);
    lines.push(`- **Verified Against:** changeset view`);
  } else {
    lines.push(`- **Active Changeset:** none`);
    lines.push(`- **Verified Against:** base model`);
  }
}

