async function createConfiguredServer() {
  const { McpServer } = await import("@modelcontextprotocol/sdk/server/mcp.js");

  const server = new McpServer({
    name: "documentation-robotics",
    version: cliVersion,
  });

  // Register the model tool surface and spec/model manifest resources.
  new McpToolRegistry().registerAll(server);
  await new McpResourceRegistry().registerAll(server);

  // Warm the model cache at startup so it's loaded once and held in memory
  // for the session, rather than waiting for the first tool call. Best-effort:
  // a server started outside a DR project still starts up cleanly — the first
  // tool call that supplies a valid rootPath will load and cache it.
  try {
    await loadModel();
  } catch (error) {
    process.stderr.write(`[mcp] model warmup skipped: ${getErrorMessage(error)}\n`);
  }

  return server;
}

async captureBaseSnapshot(changesetId: string): Promise<string> {
  this.validateChangesetId(changesetId);

  if (!this.model) {
    throw new Error("Model required for capturing base snapshot");
  }
  const changeset = await this.load(changesetId);
  if (!changeset) {
    throw new Error(`Changeset '${changesetId}' not found`);
  }

  const snapshotId = await this.snapshotManager.captureSnapshot(this.model);
  changeset.baseSnapshot = snapshotId;
  changeset.updateModified();
  await this.storage.save(changeset);

  return snapshotId;
}

/**
 * Markdown link text utilities
 */

/**
 * Format node type name for display by splitting on capital letters and title-casing
 * @param type The node type string (e.g., "CustomEndpoint")
 * @returns Formatted display name (e.g., "Custom Endpoint")
 */
export function formatNodeTypeName(type: string): string {
  return type
    .split(/(?=[A-Z])/)
    .join(" ")
    .replace(/^./, (c) => c.toUpperCase());
}

/**
 * Create descriptive link text that avoids markdownlint MD059 prohibited texts
 * Prohibited texts: "click here", "here", "link", "more"
 * @param type The node type to create link text for
 * @returns Descriptive link text safe for markdownlint MD059
 */
export function createDescriptiveLinkText(type: string): string {
  const prohibited = ["click here", "here", "link", "more"];
  const formatted = formatNodeTypeName(type);

  if (prohibited.includes(formatted.toLowerCase())) {
    // Add "node" suffix to make it descriptive
    return `${formatted} node`;
  }

  return formatted;
}
